"""BFS: Return visited nodes"""
def bfs_visited(`node: Any, graph: Any) -> object {
    queue = [`node];
    visited = [];
    while queue {
        current = queue.pop();
        queue[0:0] = [
            neighbor
            for neighbor in graph[current]
            if (neighbor not in visited)
        ];
        visited.append(current);
    }
    return visited;
}

